def transform(grid):
    h=len(grid); w=len(grid[0])
    vals={x for r in grid for x in r}
    bg=max(vals,key=lambda x:sum(r.count(x) for r in grid))
    pts=[(i,j) for i in range(h) for j in range(w) if grid[i][j]!=bg]
    if not pts:
        return [r[:] for r in grid]
    a=min(i for i,j in pts); b=max(i for i,j in pts)
    c=min(j for i,j in pts); d=max(j for i,j in pts)
    rare=min((x for x in vals if x!=bg),key=lambda x:sum(r.count(x) for r in grid))
    fill=2 if bg==6 and rare==8 else rare
    out=[r[:] for r in grid]
    for i in range(a,b+1):
        for j in range(c,d+1):
            if out[i][j]==bg:
                out[i][j]=fill
    return out

